async () => {
  const checks = [];
  const assert = (ok, label) => { if (!ok) throw new Error(label); checks.push(label); };
  const get = suffix => document.getElementById("benchmark316-" + suffix);
  const wait = async test => { for (let n = 0; n < 50; n++) { if (test()) return; await new Promise(r => setTimeout(r, 25)); } throw new Error("UI_WAIT_TIMEOUT"); };
  const change = (suffix, value) => { get(suffix).value = value; get(suffix).dispatchEvent(new Event("change")); };
  if (document.getElementById("workspace-tour").open) document.getElementById("tour-skip").click();
  const start = window.__preview.calls.length; window.__preview.realDownload = false;
  document.querySelector('[data-page="benchmark316"]').click();
  get("tab-results").click(); await wait(() => get("rows").children.length === 8);
  change("run-language", "en");
  change("split", "ALL"); get("search").value = ""; get("search").dispatchEvent(new Event("input"));
  assert(get("rows").textContent.includes("45/80"), "eight methods and real full-set scores");
  change("split", "EVALUATION");
  assert(get("case").options.length === 59 && get("rows").textContent.includes("28/52"), "reserved split counts and denominators");
  get("tab-cases").click(); get("search").value = "aws100-068"; get("search").dispatchEvent(new Event("input"));
  await wait(() => get("detail").textContent.includes("aws100-068") && !get("detail").textContent.includes("Loading"));
  assert(get("case").options.length === 1, "case search uses real collection316 cases");
  change("method", "graph_1hop");
  assert(get("detail").textContent.includes("effective Graph") && get("detail").textContent.includes("Hybrid yes; selected no"), "graph context regression is visible");
  const link = get("detail").querySelector("a");
  assert(link?.href.startsWith("https://docs.aws.amazon.com/") && link.rel.includes("noopener"), "official source links remain safe");
  const disclosure = get("detail").querySelector("details"); disclosure.open = true;
  assert(disclosure.querySelector("blockquote").textContent.length > 0, "actual supporting source quote opens");
  change("language", "vi");
  assert(get("detail").querySelector("h3").textContent.includes("Bộ cân bằng tải") || /[ộểướệ]/.test(get("detail").querySelector("h3").textContent), "Vietnamese text is available without claiming VI execution");
  change("method", "hybrid_multi_query");
  const paired = !get("run-language").querySelector('[value="vi"]').disabled;
  if (paired) {
    assert(get("detail").textContent.includes("Shared search angles") || get("detail").textContent.includes("Shared planner failed validation"), "planner method has actual saved preparation or explicit failure");
    change("run-language", "vi");
    assert(get("caption").textContent.includes("Vietnamese with shared English rewrite"), "measured Vietnamese track is distinct from text translation");
    assert(!get("rows").textContent.includes("Not run"), "all eight Vietnamese methods have recorded outcomes");
    change("run-language", "en");
  } else assert(get("detail").textContent.includes("Not run"), "missing planner method is not fabricated");
  get("export").click();
  const exported = JSON.parse(window.__preview.downloads.at(-1).text);
  assert(exported.cases.length === 100 && exported.selected_case.scenario_id === "aws100-068", "export contains public results and selected case");
  get("tab-methodology").click(); assert(get("hashes").textContent.includes(exported.protocol_sha256), "methodology carries actual protocol hash");
  assert(!window.__preview.calls.slice(start).some(c => c.method !== "GET"), "viewer never submits a model or comparison request");
  assert(document.documentElement.scrollWidth <= innerWidth, "no document horizontal overflow");
  const scroller = document.scrollingElement; scroller.scrollTop = scroller.scrollHeight;
  assert(scroller.scrollTop + innerHeight >= scroller.scrollHeight - 2, "main document reaches the bottom");
  const { createBenchmark316 } = await import("/assets/benchmark316.mjs");
  const root = document.getElementById("page-benchmark316").cloneNode(true);
  const isolatedDocument = { getElementById: id => root.querySelector(`[id="${id}"]`), createElement: tag => document.createElement(tag) };
  let resolve; const delayed = new Promise(r => { resolve = r; });
  const isolated = createBenchmark316({ document: isolatedDocument, loadData: () => delayed, download: () => {} });
  isolated.activate(); const pending = isolated.show("benchmark316"); isolated.clear(); resolve(exported); await pending;
  assert(root.querySelector("#benchmark316-rows").children.length === 0, "late summary cannot survive clear");
  const broken = createBenchmark316({ document: isolatedDocument, loadData: async () => { throw new Error("fixture"); }, download: () => {} });
  broken.activate(); await broken.show("benchmark316");
  assert(root.querySelector("#benchmark316-status").textContent.includes("unavailable"), "load failure has a recoverable state");
  return { status: "PASS", checks, width: innerWidth, height: innerHeight, recorded_model_calls: 0, new_api_posts: 0 };
}
